        "w": 560,
        "h": 100,
        "content": "В основе проекта — модульная BENTO-система, которая позволяет собирать разные типы бренд-коммуникации внутри одного визуального алгоритма. Один принцип задает структуру и узнаваемость, а гибкость композиции помогает адаптировать систему под разные индустрии — от fashion и retail до beauty, pharma и digital.",
